test("Studio uses each configured allocation, defaulting only for unlisted tenants", () => {
  const catalog = {default:5, studios:new Map([["orchid", 8], ["iris", 2]])};
  const dispatch = planner(catalog);
  assert.deepEqual(dispatch(book("orchid-full", "orchid", 8)),
