  assert.equal(dispatch(book("iris-extra", "iris", 3)).status, "full");
  assert.equal(dispatch(book("iris-full", "iris", 2)).remaining, 0);
  assert.equal(dispatch(book("unknown-extra", "rose", 6)).status, "full");
  assert.equal(dispatch(book("unknown-full", "rose", 5)).remaining, 0);
  assert.equal(dispatch(book("tomorrow", "orchid", 8, "2025-04-03")).status, "booked");
  assert.equal(catalog.default, 5);
  assert.equal(dispatch(book("archive-extra", "orchid", 6, undefined, "archive")).status, "full");
  assert.equal(dispatch(book("archive-full", "orchid", 5, undefined, "archive")).status, "booked");
});

