const replay = fileURLToPath(new URL("./replay.mjs", import.meta.url));
const read = path => JSON.parse(readFileSync(path, "utf8"));
const save = (path, data) => writeFileSync(path, JSON.stringify(data));
const book = (id, day, units) =>
  ({action:"book", service:"studio", tenant:"orchid", id, day, units});
const source = {
  edition:"orchid-quota",
  window:{service:"studio", tenant:"orchid", from:"2025-04-02", through:"2025-04-03"},
  subscriptions:[{service:"studio", tenant:"orchid"}, {service:"studio", tenant:"iris"},
                 {service:"archive", tenant:"orchid"}],
  days:["2025-04-01", "2025-04-02", "2025-04-03", "2025-04-04"],
  operations:[
    book("seed", "2025-04-01", 3),
    {action:"renew", service:"studio", previous:"seed", id:"may", day:"2025-04-02", units:7},
    book("collision", "2025-04-04", 1),
    book("collision", "2025-04-03", 8),
    book("cancelled", "2025-04-03", 4),
    {action:"cancel", service:"studio", id:"cancelled"},
    {action:"renew", service:"studio", previous:"seed", id:"last", day:"2025-04-03", units:1},
    {action:"cancel", service:"studio", id:"seed"}
  ]
};

test("publication replays all operations before selecting the audience and inclusive dates", () => {
  const rows = projectPublication(source, readCatalog());
  assert.deepEqual(rows, [
    {service:"studio", tenant:"orchid", day:"2025-04-02", edition:"orchid-quota", cap:8, used:7, available:1},
    {service:"studio", tenant:"orchid", day:"2025-04-03", edition:"orchid-quota", cap:8, used:1, available:7}
  ]);
  const empty = {...source, window:{...source.window, from:"2025-04-04", through:"2025-04-04"}, operations:[]};
  assert.equal(projectPublication(empty, readCatalog())[0].available, 8);
  const iris = {...source, window:{...source.window, tenant:"iris"}};
  assert.ok(projectPublication(iris, readCatalog()).every(row => row.cap === 5 && row.used === 0));
  const archive = {...source, window:{...source.window, service:"archive"}};
  assert.ok(projectPublication(archive, readCatalog()).every(row => row.cap === 5 && row.used === 0));
});

test("publish-calendar replaces only ticket cells and is byte-idempotent", t => {
  const dir = mkdtempSync(join(tmpdir(), "studio-publication-"));
